using Lexico.Core.Domain;
using Lexico.Core.Scheduling;
using Xunit;

namespace Lexico.Core.Tests;

public sealed class FsrsReferenceParityTests
{
    private static readonly DateTime Start = new(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc);

    // Golden states were generated by py-fsrs 6.3.2 using the pinned FSRS.Core 1.0.7
    // default parameter vector, so this isolates scheduler behavior from parameter tuning.

    public sealed record Step(
        Grade Grade,
        TimeSpan Offset,
        CardState State,
        int? LearningStep,
        double Stability,
        double Difficulty,
        double IntervalSeconds);

    public sealed record Scenario(string Name, double DesiredRetention, SrsCardSnapshot? Initial, Step[] Steps);

    public static IEnumerable<object[]> ReferenceScenarios()
    {
        static Step S(Grade grade, TimeSpan offset, CardState state, int? step, double stability, double difficulty, double seconds)
            => new(grade, offset, state, step, stability, difficulty, seconds);

        yield return [new Scenario("new Again", .9, null,
            [S(Grade.Again, TimeSpan.Zero, CardState.Learning, 0, .2172, 7.0114, 60)])];
        yield return [new Scenario("new Hard", .9, null,
            [S(Grade.Hard, TimeSpan.Zero, CardState.Learning, 0, 1.1771, 6.24313294857, 330)])];
        yield return [new Scenario("new Good", .9, null,
            [S(Grade.Good, TimeSpan.Zero, CardState.Learning, 1, 3.2602, 4.88463163481, 600)])];
        yield return [new Scenario("new Easy", .9, null,
            [S(Grade.Easy, TimeSpan.Zero, CardState.Review, null, 16.1507, 2.48243852238, 1_382_400)])];

        yield return [new Scenario("same-day Hard", .9, null,
        [
            S(Grade.Good, TimeSpan.Zero, CardState.Learning, 1, 3.2602, 4.88463163481, 600),
            S(Grade.Good, TimeSpan.FromMinutes(10), CardState.Review, null, 3.53624365562, 4.86805650234, 345_600),
            S(Grade.Hard, TimeSpan.FromMinutes(11), CardState.Review, null, 3.53624365562, 6.03886143509, 345_600),
        ])];
        yield return [new Scenario("same-day Again", .9, null,
        [
            S(Grade.Good, TimeSpan.Zero, CardState.Learning, 1, 3.2602, 4.88463163481, 600),
            S(Grade.Good, TimeSpan.FromMinutes(10), CardState.Review, null, 3.53624365562, 4.86805650234, 345_600),
            S(Grade.Again, TimeSpan.FromMinutes(11), CardState.Relearning, 0, .839845041905, 7.2261271319, 600),
        ])];
        yield return [new Scenario("first failure and relearning", .9, null,
        [
            S(Grade.Again, TimeSpan.Zero, CardState.Learning, 0, .2172, 7.0114, 60),
            S(Grade.Good, TimeSpan.FromMinutes(1), CardState.Learning, 1, .347699607632, 6.9801501658, 600),
            S(Grade.Good, TimeSpan.FromMinutes(11), CardState.Review, null, .520216703721, 6.94911595546, 86_400),
            S(Grade.Again, TimeSpan.FromDays(20), CardState.Relearning, 0, .40469995581, 8.32992871489, 600),
            S(Grade.Good, TimeSpan.FromDays(20) + TimeSpan.FromMinutes(10), CardState.Review, null, .592433022435, 8.28958103256, 86_400),
        ])];
        yield return [new Scenario("fractional long gaps", .9, null,
        [
            S(Grade.Good, TimeSpan.Zero, CardState.Learning, 1, 3.2602, 4.88463163481, 600),
            S(Grade.Good, TimeSpan.FromMinutes(10), CardState.Review, null, 3.53624365562, 4.86805650234, 345_600),
            S(Grade.Good, TimeSpan.FromDays(14) + TimeSpan.FromHours(23), CardState.Review, null, 26.6121030612, 4.85159573828, 2_332_800),
            S(Grade.Easy, TimeSpan.FromDays(44) + TimeSpan.FromHours(23), CardState.Review, null, 210.272995595, 3.64417468916, 18_144_000),
        ])];

        foreach (var (retention, learningIntervalSeconds, intervalSeconds) in new[]
                 {
                     (.1, 3_153_600_000d, 3_153_600_000d),
                     (.8, 864_000d, 26_524_800d),
                     (.9, 345_600d, 8_985_600d),
                     (.97, 86_400d, 2_160_000d),
                     (.99, 86_400d, 691_200d),
                 })
        {
            yield return [new Scenario($"retention {retention}", retention, null,
            [
                S(Grade.Good, TimeSpan.Zero, CardState.Learning, 1, 3.2602, 4.88463163481, 600),
                S(Grade.Good, TimeSpan.FromMinutes(10), CardState.Review, null, 3.53624365562, 4.86805650234, learningIntervalSeconds),
                S(Grade.Easy, TimeSpan.FromDays(30) + TimeSpan.FromHours(12), CardState.Review, null, 103.602579932, 3.66433004146, intervalSeconds),
            ])];
        }

        yield return [new Scenario("extreme interval and max cap", .9,
            new SrsCardSnapshot(CardState.Review, null, 100_000_000, 5, Start, Start),
            [S(Grade.Good, TimeSpan.FromDays(1), CardState.Review, null, 100_000_000.495, 4.9826288258, 3_153_600_000)])];
    }

    [Theory]
    [MemberData(nameof(ReferenceScenarios))]
    public void MatchesPyFsrs632ForEachReview(Scenario scenario)
    {
        var engine = new FsrsCoreEngine(scenario.DesiredRetention, enableFuzzing: false);
        var card = scenario.Initial ?? new SrsCardSnapshot(CardState.Learning, 0, null, null, Start, null);

        foreach (var expected in scenario.Steps)
        {
            var now = Start + expected.Offset;
            var result = engine.Schedule(card, expected.Grade, now);
            card = result.UpdatedCard;

            Assert.True(card.State == expected.State,
                $"{scenario.Name}: expected state {expected.State}, got {card.State}");
            Assert.Equal(expected.LearningStep, card.Step);
            AssertReferenceNumber(expected.Stability, card.Stability!.Value);
            AssertReferenceNumber(expected.Difficulty, card.Difficulty!.Value);
            Assert.Equal(expected.IntervalSeconds, (card.DueUtc - now).TotalSeconds, 5);
        }
    }

    [Fact]
    public void PredictRecallUsesWholeElapsedDaysLikePyFsrs()
    {
        var engine = new FsrsCoreEngine(enableFuzzing: false);
        var card = new SrsCardSnapshot(CardState.Review, null, 37, 5, Start, Start);

        var recall = engine.PredictRecall(card, Start.AddDays(14).AddHours(23));

        AssertReferenceNumber(.9544649884884714, recall);
    }

    private static void AssertReferenceNumber(double expected, double actual)
    {
        double tolerance = 1e-10 * Math.Max(1, Math.Abs(expected));
        Assert.InRange(actual, expected - tolerance, expected + tolerance);
    }
}
